CREATE OR REPLACE FUNCTION private.final_effective_snapshot() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE u record; rules_ jsonb; role_p text[]; custom_p text[]; allow_p text[]; deny_p text[]; use_ boolean; mode_ text; effective_ jsonb; result_ jsonb:='[]'; cfg jsonb; BEGIN cfg:=private.base_config(); FOR u IN SELECT id,status FROM profiles LOOP
 rules_:=private.base_rules(u.id,cfg);
 SELECT coalesce(array_agg(DISTINCT p),'{}') INTO role_p FROM user_roles ur JOIN app_roles r ON r.id=ur.role_id CROSS JOIN LATERAL unnest(r.permissions)p WHERE ur.user_id=u.id;
 SELECT use_custom,mode,permissions INTO use_,mode_,custom_p FROM user_permission_overrides WHERE user_id=u.id;
 SELECT coalesce(array_agg(DISTINCT x->>'permission') FILTER(WHERE x->>'effect'='ALLOW'),'{}'),coalesce(array_agg(DISTINCT x->>'permission') FILTER(WHERE x->>'effect'='DENY'),'{}') INTO allow_p,deny_p FROM jsonb_array_elements(rules_)x;
 SELECT coalesce(jsonb_agg(c.key ORDER BY c.key),'[]') INTO effective_ FROM base_permission_catalog c WHERE private.is_active(u.id) AND (private.is_super_admin(u.id) OR CASE WHEN (private.org_role_permission_ready(c.key) OR private.mkt_specialty_permission_ready(c.key) OR c.key LIKE 'sale_work.%') AND c.key=ANY(deny_p) THEN false WHEN (private.org_role_permission_ready(c.key) OR private.mkt_specialty_permission_ready(c.key) OR c.key LIKE 'sale_work.%') AND c.key=ANY(allow_p) THEN true WHEN coalesce(use_,false) AND mode_='replace' THEN c.key=ANY(coalesce(custom_p,'{}')) ELSE c.key=ANY(role_p) OR (coalesce(use_,false) AND mode_='additive' AND c.key=ANY(coalesce(custom_p,'{}'))) END);
 result_:=result_||jsonb_build_array(jsonb_build_object('user_id',u.id,'permissions',effective_,'rules',rules_));END LOOP;RETURN result_;END $$;
DO $$ DECLARE d text;old_ text:=$s$(SELECT coalesce(jsonb_agg(jsonb_build_object('user_id',p.id,'permissions',(SELECT coalesce(jsonb_agg(r.key ORDER BY r.key),'[]') FROM base_permission_catalog r WHERE private.has_permission(p.id,r.key)))),'[]') FROM profiles p)$s$;BEGIN SELECT pg_get_functiondef('public.base_perm_final_execute(uuid[],text,text)'::regprocedure) INTO d; IF strpos(d,old_)=0 THEN RAISE EXCEPTION 'Unexpected snapshot contract';END IF; EXECUTE replace(d,old_,'private.final_effective_snapshot()');END $$;
REVOKE ALL ON FUNCTION private.final_effective_snapshot() FROM PUBLIC,anon,authenticated,service_role;